settings.custom_liquid:
{%- liquid
  assign v = product.selected_or_first_available_variant
  assign price = v.price | money_without_currency | remove: '.00'
-%}
{%- liquid
  assign b1 = all_products['6k']
  assign b2 = all_products['كتاب-أهم-1000-كلمة']
  assign b3 = all_products['كتاب-الاكسينت']
  assign b4 = all_products['كورس-الجرامر']
  assign sum = b1.price | plus: b2.price | plus: b3.price | plus: b4.price
  assign save = sum | minus: v.price
  assign sum_txt = sum | money_without_currency | remove: '.00'
  assign save_txt = save | money_without_currency | remove: '.00'
-%}
<style>

/* FZL landers: نفس ستايل صفحة الـ 6000. كل حاجة متقفلة تحت .fzl */
body:has(.fzl){background:#fdf8ee}
.t4s-container:has(.fzl),.t4s-row:has(.fzl),.t4s-col-item:has(.fzl),.t4s-col-inner:has(.fzl){padding-left:0!important;padding-right:0!important;margin-left:0!important;margin-right:0!important;max-width:100%!important;--ts-gx:0px}
.fzl{direction:rtl;max-width:480px;margin:0 auto;background:#fdf8ee;color:#1f1a2e;font-family:'IBM Plex Sans Arabic',system-ui,sans-serif;font-size:16px;line-height:1.65;padding-bottom:24px;text-align:right;overflow-x:hidden}
.fzl *,.fzl-fixed *{box-sizing:border-box;font-family:'IBM Plex Sans Arabic',system-ui,sans-serif}
.fzl h1,.fzl h2,.fzl p,.fzl ul{margin:0;padding:0;color:inherit;letter-spacing:0;text-transform:none;font-family:inherit}
.fzl img{max-width:100%;margin:0}
.fzl h2{font-size:28px;font-weight:700;line-height:1.3;margin-bottom:16px}
.fzl-sec{padding:40px 20px 8px}
.fzl-top{background:#2b9d9d;color:#fff;text-align:center;font-size:13px;font-weight:600;padding:9px 16px}
.fzl h1{font-size:34px;line-height:1.25;font-weight:700}
.fzl h1 span{color:#e91e8c}
.fzl-sub{margin-top:14px!important;font-size:16px;color:#4a4458}
.fzl-heroimg{position:relative;margin-top:20px;height:360px}
.fzl-heroimg:before{content:"";position:absolute;inset:40px -40px 0 -40px;background:#f6d40a;border-radius:50% 50% 0 0/60% 60% 0 0}
.fzl-heroimg img{position:absolute;top:0;bottom:0;left:24px;right:24px;width:calc(100% - 48px);height:100%;object-fit:cover;object-position:center 30%;border-radius:24px 24px 0 0;box-shadow:0 16px 40px rgba(31,26,46,.18)}
.fzl-pricebox{background:#f6d40a;padding:20px 20px 28px;display:flex;flex-direction:column;gap:14px}
.fzl-price{display:flex;align-items:baseline;gap:10px}
.fzl-price b{font-size:32px;font-weight:700;line-height:1}
.fzl-price span{font-size:15px;font-weight:600}
.fzl-cta{display:flex;align-items:center;justify-content:center;width:100%;min-height:58px;background:#e91e8c!important;color:#fff!important;font-size:20px;font-weight:700;text-decoration:none!important;border:0;border-radius:16px;box-shadow:0 8px 20px rgba(233,30,140,.3);cursor:pointer;padding:0 16px}
.fzl-cta:hover{background:#c9157a!important;color:#fff!important}
.fzl-by{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:500}
.fzl-by img{width:36px;height:36px;border-radius:50%;object-fit:cover;border:2px solid #fff}
.fzl-zoom{display:block;width:100%;padding:0;border:0;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 30px rgba(31,26,46,.12);cursor:zoom-in;position:relative}
.fzl-zoom img{display:block;width:100%;height:auto}
.fzl-zoom span{position:absolute;bottom:12px;left:12px;display:inline-flex;align-items:center;gap:6px;background:#1f1a2e;color:#fff;font-size:13px;font-weight:600;padding:7px 12px;border-radius:999px}
.fzl-card{background:#fff;border-radius:20px;padding:20px;border:2px solid #efe3cf}
.fzl-ex{margin-top:18px}
.fzl-ex .lbl{font-size:14px;font-weight:700;color:#117f7f;margin-bottom:10px}
.fzl-ex ul{list-style:none;display:flex;flex-direction:column;gap:12px}
.fzl-ex li{display:flex;flex-direction:column;gap:2px}
.fzl-ex li .en{direction:ltr;text-align:right;font-weight:600;font-size:17px}
.fzl-ex li .ar{color:#4a4458}
.fzl-tag{display:inline-block;font-size:12px;font-weight:700;padding:1px 8px;border-radius:999px;margin-right:4px}
.fzl-tag.f{background:#e0f3f3;color:#117f7f}.fzl-tag.s{background:#fde2f0;color:#c2126f}
.fzl-play{margin-top:18px;display:inline-flex;align-items:center;gap:10px;background:#2b9d9d;color:#fff;border:0;border-radius:999px;padding:12px 18px 12px 14px;font-size:15px;font-weight:700;cursor:pointer}
.fzl-play i{display:inline-flex;width:28px;height:28px;border-radius:50%;background:#fff;color:#2b9d9d;align-items:center;justify-content:center}
.fzl-probs{display:flex;flex-direction:column;gap:12px}
.fzl-prob{display:flex;align-items:center;gap:14px;background:#fff;border-radius:18px;padding:16px 18px;border:2px solid #efe3cf;font-size:17px;font-weight:600}
.fzl-prob i{flex:none;width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center}
.fzl-how{margin-top:40px;background:#2b9d9d;color:#fff;padding:36px 20px 40px}
.fzl-how h2{margin-bottom:22px}
.fzl-step{display:flex;align-items:center;gap:16px;font-size:19px;font-weight:600;margin-bottom:18px}
.fzl-step b{flex:none;font-size:48px;font-weight:700;line-height:1;color:#f6d40a;width:56px}
.fzl-note{margin-top:8px!important;font-size:16px;font-weight:500;background:rgba(255,255,255,.14);border-radius:14px;padding:12px 16px!important;display:inline-block}
.fzl-inside{display:block;width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:20px}
.fzl-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.fzl-chips span{background:#fff;border:2px solid #efe3cf;border-radius:999px;padding:7px 14px;font-size:15px;font-weight:600}
.fzl-idx{margin-top:18px;display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:52px;background:#fff;color:#117f7f;border:2px solid #2b9d9d;border-radius:14px;font-size:16px;font-weight:700;cursor:pointer}
.fzl-shots{display:flex;gap:14px;overflow-x:auto;padding:4px 20px 12px;scroll-snap-type:x mandatory;scrollbar-width:none;align-items:flex-start;-webkit-overflow-scrolling:touch}
.fzl-shots::-webkit-scrollbar{display:none}
.fzl-shots img{flex:0 0 280px;width:280px;height:auto;border-radius:18px;scroll-snap-align:start;box-shadow:0 8px 24px rgba(31,26,46,.12)}
.fzl-hint{font-size:13px;color:#4a4458;padding:0 20px}
.fzl-author{margin:40px 20px 0;background:#fde2f0;border-radius:24px;padding:22px;display:flex;align-items:center;gap:16px}
.fzl-author img{flex:none;width:96px;height:96px;border-radius:50%;object-fit:cover;border:4px solid #fff}
.fzl-author h2{font-size:22px;margin-bottom:6px}
.fzl-author p{font-size:15px;color:#4a4458}
.fzl-list{list-style:none;display:flex;flex-direction:column;gap:10px}
.fzl-list li{display:flex;align-items:center;gap:12px;font-size:16px;font-weight:500}
.fzl-ck{flex:none;width:28px;height:28px;border-radius:50%;background:#2b9d9d;color:#fff;display:flex;align-items:center;justify-content:center}
.fzl-offer{margin-top:18px;background:#f6d40a;border-radius:18px;padding:16px 18px;display:flex;flex-direction:column;gap:4px}
.fzl-offer b{font-size:28px;font-weight:700;line-height:1.2}
.fzl-offer span{font-size:15px;font-weight:600}
.fzl-buy{margin:18px 0 0}
.fzl-wa{display:block;text-align:center;font-size:14px;font-weight:600;color:#117f7f!important;margin-top:12px}
.fzl-faq{display:flex;flex-direction:column;gap:10px}
.fzl-faq details{background:#fff;border:2px solid #efe3cf;border-radius:16px;padding:0 18px}
.fzl-faq summary{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 0;font-weight:700;font-size:16px;list-style:none;cursor:pointer}
.fzl-faq summary::-webkit-details-marker{display:none}
.fzl-faq summary svg{flex:none;transition:transform .2s}
.fzl-faq details[open] summary svg{transform:rotate(45deg)}
.fzl-faq p{padding:0 0 16px!important;font-size:15px;color:#4a4458}
/* sticky + lightbox (بيتنقلوا للـ body بالـ JS) */
.fzl-lb{position:fixed;inset:0;z-index:10000;background:rgba(31,26,46,.92);display:none;align-items:center;justify-content:center;padding:16px;cursor:zoom-out}
.fzl-lb.on{display:flex}
.fzl-lb img{max-width:min(92vw,900px);max-height:88vh;width:auto;height:auto;border-radius:12px}
.fzl-lb iframe{width:min(92vw,720px);aspect-ratio:16/9;border:0;border-radius:12px;background:#000}
.fzl-lb button{position:absolute;top:16px;left:16px;width:44px;height:44px;border-radius:50%;border:0;background:#fff;color:#1f1a2e;font-size:22px;cursor:pointer}
@media (min-width:768px){.fzl{margin-top:24px;margin-bottom:24px;border-radius:24px;box-shadow:0 10px 40px rgba(31,26,46,.08)} }

.t4s-section-inner:has(.fzl),.t4s-code__liquid:has(.fzl){margin:0!important;padding:0!important}
.fzl-price s{font-size:16px;font-weight:600;color:#4a4458}
.fzl-zoom img{max-height:420px;object-fit:cover;object-position:top}
.fzl-shots button{flex:0 0 240px;padding:0;border:0;background:none;cursor:zoom-in;scroll-snap-align:start}
.fzl-shots button img{width:240px;height:auto;border-radius:16px;box-shadow:0 8px 24px rgba(31,26,46,.12);display:block}
.fzl-shots.rv img{flex:0 0 280px;width:280px}
.fzl-sec .fzl-shots{margin-left:-20px;margin-right:-20px}
.fzl-sec .fzl-hint{padding:0}
.fzl-ex .q{direction:ltr;text-align:right;font-weight:700;font-size:18px;margin-bottom:2px}
.fzl-ex .qa{color:#4a4458;margin-bottom:12px}
.fzl-ex .why{background:#fdf8ee;border-radius:14px;padding:12px 14px;font-size:15px}
.fzl-ex .why b{color:#117f7f}
.fzl-words{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0;direction:ltr;justify-content:flex-end}
.fzl-words span{background:#e0f3f3;color:#117f7f;border-radius:999px;padding:4px 12px;font-weight:600;font-size:15px}
.fzl-sent{direction:ltr;text-align:right;font-weight:600;font-size:16px}
.fzl-video{position:relative;border-radius:20px;overflow:hidden;background:#000;box-shadow:0 10px 30px rgba(31,26,46,.12)}
.fzl-video video{display:block;width:100%;height:auto;aspect-ratio:16/9}
.fzl-cap{font-size:13px;color:#4a4458;margin-top:8px!important}
.fzl-app{margin-top:40px;background:#fff;border-top:2px solid #efe3cf;border-bottom:2px solid #efe3cf;padding:36px 0 28px}
.fzl-app h2,.fzl-app .fzl-list{margin-left:20px;margin-right:20px}
.fzl-app .fzl-list{margin-top:18px}
.fzl-free{display:inline-block;margin:14px 20px 0!important;background:#f6d40a;border-radius:999px;padding:6px 14px!important;font-size:14px;font-weight:700}
.fzl-kit{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.fzl-kit div{background:#fff;border:2px solid #efe3cf;border-radius:18px;padding:10px;display:flex;flex-direction:column;gap:6px}
.fzl-kit img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:12px}
.fzl-kit b{font-size:15px;line-height:1.35}
.fzl-kit span{font-size:13px;color:#4a4458;line-height:1.5}
.fzl-kit s{font-size:13px;color:#4a4458;margin-top:auto}
.fzl-save{margin-top:14px;background:#fff;border:2px dashed #2b9d9d;border-radius:18px;padding:14px 16px;font-size:16px;font-weight:600;text-align:center}
.fzl-save s{color:#4a4458}
.fzl-save b{color:#e91e8c}
.fzl-lb video{max-width:min(92vw,900px);max-height:84vh;border-radius:12px;background:#000}

/* 9-11: price box in the first screen (same layout as the 6k hero) */
.fzl-hh{padding:16px 20px 12px}
.fzl .fzl-hh h1{font-size:26px;line-height:1.3}
.fzl .fzl-hh .fzl-sub{margin-top:6px!important;font-size:15px;line-height:1.55}
.fzl .fzl-hp{padding:16px 16px 20px;gap:12px}
.fzl-hrow{display:flex;gap:14px;align-items:center}
.fzl .fzl-hp .fzl-heroimg{flex:0 0 132px;height:188px;margin:0;overflow:hidden;border-radius:14px;box-shadow:0 8px 20px rgba(31,26,46,.22);cursor:zoom-in}
.fzl .fzl-hp .fzl-heroimg:before{display:none}
.fzl .fzl-hp .fzl-heroimg img{position:static;width:100%;height:100%;object-fit:cover;object-position:center 40%;border-radius:0;box-shadow:none}
.fzl-heroimg-badge{position:absolute;bottom:8px;right:50%;transform:translateX(50%);background:#1f1a2e;color:#fff;font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;white-space:nowrap;z-index:2;pointer-events:none}
.fzl-hinfo{flex:1;min-width:0;display:flex;flex-direction:column;gap:8px}
.fzl .fzl-hp .fzl-price{flex-wrap:wrap;row-gap:2px}
.fzl .fzl-hp .fzl-price b{font-size:30px}
.fzl .fzl-hp .fzl-price s{font-size:18px}
.fzl-cod{font-size:14px!important;font-weight:600;line-height:1.5}
.fzl-cod b{color:#0f766e}
/* 9-11: box items + problem cards open a sample page */
.fzl-kit>div[data-lb-img]{cursor:zoom-in;position:relative}
.fzl-kit em.fzl-zm{position:absolute;top:16px;left:16px;background:#1f1a2e;color:#fff;font-style:normal;font-size:11.5px;font-weight:700;line-height:1.4;padding:4px 9px;border-radius:999px;pointer-events:none}
.fzl-prob[data-lb-img]{cursor:pointer}
.fzl-prob .fzl-chev{flex:none;margin-right:auto;color:#117f7f}

</style>
<div class="fzl" dir="rtl" lang="ar">
<section>
<div class="fzl-hh">
<h1>فاهم إنجليزي… <span>بس مش عارف تتكلم بثقة؟</span></h1>
<p class="fzl-sub">جمل + كلمات + جرامر + نطق أمريكي في بوكس واحد، كله بالعامية وبصوتيات أمريكية.</p>
</div>
<div class="fzl-pricebox fzl-hp">
<div class="fzl-hrow">
<div class="fzl-heroimg" data-lb-img="{{ product.featured_media.preview_image | image_url: width: 1400 }}" role="button" aria-label="كبّر صورة البوكس">{{ product.featured_media.preview_image | image_url: width: 400 | image_tag: fetchpriority: 'high', widths: '264, 400', sizes: '132px', alt: product.title }}<span class="fzl-heroimg-badge">شوف البوكس</span></div>
<div class="fzl-hinfo">
<div class="fzl-price"><b>{{ price }} جنيه</b>{%- if save > 0 -%}<s>{{ sum_txt }}</s>{%- endif -%}</div>
<p class="fzl-cod">الدفع عند الاستلام{%- if save > 0 -%}<br><b>وفّر {{ save_txt }} جنيه</b> عن شراهم لوحدهم{%- endif -%}</p>
</div>
</div>
<a href="#fzl-order" class="fzl-cta" data-fzl-go>اطلب البوكس · {{ price }} جنيه</a>
<div class="fzl-by"><img src="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/fg.jpg?crop=region&crop_left=600&crop_top=0&crop_width=840&crop_height=840&width=96&height=96" width="36" height="36" alt="فيروز الجندي"><span>من فيروز الجندي · +90,000 طالب</span></div>
</div>
</section>
<section class="fzl-sec">
<h2>اللي في البوكس</h2>
<div class="fzl-kit">
<div data-lb-img="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/6000_3.webp?width=1400" role="button" aria-label="شوف صفحة من كتاب أهم 6000 جملة"><em class="fzl-zm">شوف صفحة</em><img src="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/IMG_0400_2048x2048_bcd069e0-02a4-4124-b9a6-287b80b83c57.jpg?width=400&height=400&crop=center" width="400" height="400" loading="lazy" alt="كتاب أهم 6000 جملة"><b>كتاب أهم 6000 جملة</b><span>395 موقف من يومك بجمل جاهزة تقولها</span>{%- if b1.price > 0 -%}<s>لوحده {{ b1.price | money_without_currency | remove: '.00' }} جنيه</s>{%- endif -%}</div>
<div data-lb-img="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/1000_2.png?width=1400" role="button" aria-label="شوف صفحة من كتاب أهم 1000 كلمة"><em class="fzl-zm">شوف صفحة</em>{{ b2.featured_media.preview_image | image_url: width: 400 | image_tag: loading: 'lazy', alt: 'كتاب أهم 1000 كلمة' }}<b>كتاب أهم 1000 كلمة</b><span>حوالي 1000 كلمة في 26 موضوع، بالصور والنطق</span>{%- if b2.price > 0 -%}<s>لوحده {{ b2.price | money_without_currency | remove: '.00' }} جنيه</s>{%- endif -%}</div>
<div data-lb-img="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/2_a1f783d5-21d8-47db-b4a4-58207e5cdfdb.png?width=1400" role="button" aria-label="شوف صفحة من كتيب الـ Accent"><em class="fzl-zm">شوف صفحة</em>{{ b3.featured_media.preview_image | image_url: width: 400 | image_tag: loading: 'lazy', alt: 'كتيب الـ Accent بالعامية' }}<b>كتيب الـ Accent بالعامية</b><span>الـ T والـ R الأمريكي والـ ed والـ ing</span>{%- if b3.price > 0 -%}<s>لوحده {{ b3.price | money_without_currency | remove: '.00' }} جنيه</s>{%- endif -%}</div>
<div data-lb-img="https://cdn.shopify.com/s/files/1/0989/0676/7726/files/2_fc491d28-e417-4c15-bdbe-3364543b52c9.png?width=1400" role="button" aria-label="شوف صفحة من كتيب الجرامر"><em class="fzl-zm">شوف صفحة</em>{{ b4.featured_media.preview_image | image_url: width: 400 | image_tag: loading: 'lazy', alt: 'كورس الجرامر' }}<b>كورس الجرامر</b><span>9 دروس فيديو + كتيب تدريبات فيه +2000 سؤال</span>{%- if b4.price > 0 -%}<s>لوحده {{ b4.price | money_without_currency | remove: '.00' }} جنيه</s>{%- endif -%}</div>
</div>
{%- if save > 0 -%}<div class="fzl-save">لو اشتريتهم لوحدهم: <s>{{ sum_txt }} جنيه</s><br>في البوكس: {{ price }} جنيه · <b>وفّر {{ save_txt }} جنيه</b></div>{%- endif -%}
</section>
