<script>
(function(){
  /* 9-11: the 1000-word book is already in the box, so hide that EasySell order bump on the Kit page only. Long-term fix: EasySell app settings. */
  var RX=/1000\s*كلمة/;
  function kill(){
    var list=document.querySelectorAll('.es-bumps [class^="es-bump-"]');
    for(var i=0;i<list.length;i++){
      var b=list[i]; if(b.getAttribute('data-fzl-hide')==='1' || !RX.test(b.textContent)) continue;
      var inp=b.querySelector('input.bump-checkbox-input');
      if(inp && inp.checked){ var t=b.querySelector('.bump-checkbox'); if(t){ t.click(); } }
      b.style.setProperty('display','none','important'); b.setAttribute('data-fzl-hide','1');
    }
    var wraps=document.querySelectorAll('.es-bumps');
    for(var j=0;j<wraps.length;j++){
      var w=wraps[j], vis=w.querySelectorAll('[class^="es-bump-"]:not([data-fzl-hide="1"])');
      if(w.querySelector('[class^="es-bump-"]') && !vis.length){ w.style.setProperty('display','none','important'); }
    }
  }
  kill();
  new MutationObserver(kill).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
<script>
(function(){
  var root=document.querySelector('.fzl'); if(!root||root.dataset.ready) return; root.dataset.ready=1;
  var lb=root.querySelector('.fzl-lb'); document.body.appendChild(lb); var box=lb.querySelector('.fzl-lb-in');
  function open(html){box.innerHTML=html;lb.classList.add('on');document.documentElement.style.overflow='hidden';}
  function close(){lb.classList.remove('on');box.innerHTML='';document.documentElement.style.overflow='';}
  root.addEventListener('click',function(e){
    var i=e.target.closest('[data-lb-img]'); if(i){e.preventDefault();open('<img src="'+i.getAttribute('data-lb-img')+'" alt="">');return;}
    var v=e.target.closest('[data-lb-video]'); if(v){e.preventDefault();open('<video src="'+v.getAttribute('data-lb-video')+'" controls autoplay playsinline></video>');return;}
    var g=e.target.closest('[data-fzl-go]'); if(g){e.preventDefault();
      var t=document.getElementById('easysell')||document.getElementById('fzl-order'); t.scrollIntoView({behavior:'smooth',block:'start'});
      var f=document.querySelector('#easysell input:not([type=hidden]):not([type=checkbox])'); if(f){setTimeout(function(){try{f.focus({preventScroll:true});}catch(x){}},600);}
    }
  });
  lb.addEventListener('click',function(e){if(e.target===lb||e.target.tagName==='BUTTON')close();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});
})();
</script>
